// ─── File: src/test/java/com/bank/finallydemo/FinallyBlockTest.java ───
package com.bank.finallydemo;

import com.bank.finallydemo.service.FinallyDemoService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class FinallyBlockTest {

    FinallyDemoService service = new FinallyDemoService();

    @BeforeEach
    void setup() { service.clearLog(); }

    @Test
    void finally_runsAfterNormalTry() {
        service.normalFlow();
        assertThat(service.getLog()).containsExactly("TRY", "FINALLY");
    }

    @Test
    void finally_runsAfterCatch() {
        service.exceptionFlow();
        assertThat(service.getLog()).containsExactly("TRY", "CATCH", "FINALLY");
    }

    @Test
    void finally_runsEvenWhenExceptionNotCaught() {
        assertThatThrownBy(() -> service.unhandledFlow())
            .isInstanceOf(RuntimeException.class);
        assertThat(service.getLog()).containsExactly("TRY", "FINALLY");
        // CATCH not present (no catch block), but FINALLY still runs!
    }

    @Test
    void finally_returnOverridesTryReturn() {
        int result = service.returnGotcha();
        assertThat(result).isEqualTo(2);  // NOT 1! finally's return wins.
        // (Caution) NEVER return from finally — confusing, unexpected behavior!
    }

    @Test
    void finally_doesNotRunAfterSystemExit() {
        // System.exit(0) → JVM terminates → finally skipped
        // Cannot test directly (would kill test JVM!)
        // But the behavior is: finally does NOT execute after System.exit.
        assertThat(true).isTrue();
    }

    @Test
    void tryWithResources_replacesFinally() throws Exception {
        // Modern: try-with-resources auto-closes AutoCloseable
        var closed = new java.util.concurrent.atomic.AtomicBoolean(false);
        try (AutoCloseable resource = () -> closed.set(true)) {
            // use resource
        }
        assertThat(closed.get()).isTrue();  // auto-closed! No finally needed!
    }

    @Test
    void executionOrder() {
        // TRY → (CATCH if exception) → FINALLY → return to caller
        // FINALLY always runs BETWEEN catch and actual return.
        service.exceptionFlow();
        assertThat(service.getLog().indexOf("TRY")).isLessThan(
            service.getLog().indexOf("CATCH"));
        assertThat(service.getLog().indexOf("CATCH")).isLessThan(
            service.getLog().indexOf("FINALLY"));
    }
}
